"""Bounded native Flash raster with the candidate embedded SY font + actual row.
Run via client-background. Does not construct the GPU page or change resources.
"""
from pathlib import Path
import argparse,hashlib,importlib.util,json,struct,subprocess
HERE=Path(__file__).resolve().parent
import bootstrap
from input_config import input_path,input_sha,runtime,work_path
def sha(b):return hashlib.sha256(b).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--out',required=True);args=ap.parse_args();out=Path(args.out).resolve();assert out.is_relative_to(work_path()) and not out.exists();out.mkdir()
 ref=input_path('raster_helper');spec=importlib.util.spec_from_file_location('existing_native_raster_helpers',ref);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
 swf=input_path('ui_partial');assert sha(swf.read_bytes())==input_sha('ui_partial')
 layout=json.loads((HERE/'native-option-row-layout.json').read_text('utf-8'));rows=[]
 for text in layout['layout']['children']['texts']:
  rows.append({'name':text['name'],'text':'队友特效' if text['name']=='title' else '关闭后隐藏队友演出和特效。','attributes':text['attributes'],'matrix':text['frames'][0]['matrix']})
 m.REF=input_path('compositor_source');original=m.REF.read_text('utf-8');render=m.method(original,'renderText').replace('starling.text.TextFormat','Object').replace('TextOptions','Object').replace('SystemUtil.isEmbeddedFont(param4.font,param4.bold,param4.italic)','true').replace('Texture.getMaxSize(param5.textureFormat)','4096').replace('MathUtil.max','Math.max');autoscale=m.method(original,'autoScaleNativeTextField')
 source='''package {import flash.display.*;import flash.geom.*;import flash.text.*;import flash.filesystem.*;import flash.desktop.NativeApplication;public class Raster extends Sprite {private static var sNativeTextField:TextField=new TextField();private static var sNativeFormat:TextFormat=new TextFormat();private static var sHelperMatrix:Matrix=new Matrix();public function Raster(){var result:Object;var measured:Array=[];try{Font.registerFont(ProbeFont);var font:Font=new ProbeFont();if(font.fontName!="SY")throw new Error("font");var canvas:BitmapData=new BitmapData(920,172,true,0);var prior:Rectangle;for each(var r:Object in ROWS){var a:Object=r.attributes;if(!font.hasGlyphs(r.text))throw new Error("glyph missing "+r.name);var fmt:Object={font:font.fontName,bold:false,italic:false,horizontalAlign:"left",thickness:a.thickness};fmt.toNativeFormat=function(n:TextFormat):void {n.font=font.fontName;n.size=a.fontSize;n.color=0x444444;n.bold=false;n.italic=false;n.align="left";n.kerning=false;n.leading=a.lineSpacing;n.letterSpacing=a.letterSpacing;};var opts:Object={textureScale:1,styleSheet:null,wordWrap:false,isHtmlText:false,autoScale:true,textureFormat:"bgra",padding:0};var b:BitmapDataEx=renderText(a.width,a.height,r.text,fmt,opts);var box:Rectangle=b.getColorBoundsRect(0xff000000,0,false);var localBox:Rectangle=box.clone();if(localBox.x<0||localBox.y<0||localBox.right>b.width||localBox.bottom>b.height)throw new Error("native texture clips glyph");box.offset(r.matrix.tx,r.matrix.ty);var same:Boolean=Number(sNativeTextField.defaultTextFormat.size)==Number(a.fontSize);var fits:Boolean=box.right<748&&box.bottom<=120&&box.width>0;if(!same||!fits)throw new Error("row clipped/shrunk "+r.name);if(prior&&prior.intersects(box))throw new Error("title description overlap");measured.push({name:r.name,text:r.text,glyphs:true,configuredFont:a.fontSize,renderedFont:sNativeTextField.defaultTextFormat.size,field:[a.width,a.height],pixels:[box.x,box.y,box.width,box.height],switchOriginX:748,noOverlapSwitchOrBelowOriginalRow:true,noShrink:true,localPixels:[localBox.x,localBox.y,localBox.width,localBox.height],bitmap:[b.width,b.height],qaCanvasPadding:16});canvas.copyPixels(b,b.rect,new Point(r.matrix.tx+16,r.matrix.ty+16),null,null,true);prior=box;b.dispose();}var png:FileStream=new FileStream();png.open(new File(File.applicationDirectory.nativePath).resolvePath("row-text.png"),FileMode.WRITE);png.writeBytes(canvas.encode(canvas.rect,new PNGEncoderOptions()));png.close();result={passed:true,font:font.fontName,rows:measured,qaCanvasPadding:16,scope:"actual candidate embedded font/native Flash raster/copied native compositor sizing algorithm; exact actual row attributes; no GPU or full scene"};}catch(e:Error){result={passed:false,error:e.toString(),stack:e.getStackTrace(),rows:measured};}var f:FileStream=new FileStream();f.open(new File(File.applicationDirectory.nativePath).resolvePath("result.json"),FileMode.WRITE);f.writeUTFBytes(JSON.stringify(result));f.close();NativeApplication.nativeApplication.exit(result.passed?0:1);}RENDER AUTO}}import flash.display.BitmapData;class BitmapDataEx extends BitmapData {public function BitmapDataEx(w:int,h:int){super(w,h,true,0);}public function get scale():Number{return 1;}}'''.replace('ROWS',json.dumps(rows,ensure_ascii=False)).replace('RENDER',render).replace('AUTO',autoscale)
 (out/'Raster.as').write_text(source,'utf-8');(out/'ProbeFont.as').write_text('package {import flash.text.Font;public class ProbeFont extends Font {}}','utf-8')
 cfg=runtime();sdk=Path(cfg['sdk']);run=subprocess.run([cfg['java'],'-Dflexlib='+str(sdk/'frameworks'),'-jar',str(sdk/'lib/mxmlc-cli.jar'),'+configname=air','-swf-version=44','-compiler.float=false','-debug=true','-compress=false','-source-path='+str(out),'-includes=ProbeFont','-output='+str(out/'Raster.swf'),str(out/'Raster.as')],capture_output=True,timeout=60);(out/'compile.log').write_bytes(run.stdout+run.stderr);assert run.returncode==0
 _,_,prod=m.tags(swf.read_bytes());fonts=[(t,d) for t,d in prod if t in (75,88) and d[:2]==b'\x10\x00'];assert len(fonts)==2
 header,rect,fixture=m.tags((out/'Raster.swf').read_bytes());symbols=0
 for i,(t,d) in enumerate(fixture):
  if t==76:count,=struct.unpack_from('<H',d);fixture[i]=(t,struct.pack('<H',count+1)+d[2:]+struct.pack('<H',16)+b'ProbeFont\0');symbols+=1
 assert symbols==1;at=next(i for i,(t,d) in enumerate(fixture) if t==82);fixture[at:at]=fonts;data=rect+b''.join(m.encode(t,d) for t,d in fixture);(out/'Raster.swf').write_bytes(b'FWS'+header[3:4]+struct.pack('<I',len(data)+8)+data)
 (out/'provenance.json').write_text(json.dumps({'input_swf':str(swf),'input_sha256':sha(swf.read_bytes()),'resource':layout,'font_tags':[{'tag':t,'sha256':sha(d)} for t,d in fonts],'native_compositor_source':str(m.REF),'native_compositor_source_sha256':sha(original.encode()),'copied_render_sha256':sha(m.method(original,'renderText').encode()),'scope':'read-only resource and font; data type/GPU capacity adapters only'},ensure_ascii=False,indent=2),'utf-8')
 launcher=(HERE.parent/'storage-validation/Launcher.as').read_text('utf-8').replace('"Harness.swf"','"Raster.swf"').replace('public function Launcher(){','public function Launcher(){NativeApplication.nativeApplication.autoExit=false;');(out/'Launcher.as').write_text(launcher,'utf-8');run=subprocess.run([cfg['java'],'-Dflexlib='+str(sdk/'frameworks'),'-jar',str(sdk/'lib/mxmlc-cli.jar'),'+configname=air','-debug=true','-output='+str(out/'Launcher.swf'),str(out/'Launcher.as')],capture_output=True,timeout=60);(out/'launcher-compile.log').write_bytes(run.stdout+run.stderr);assert run.returncode==0
 (out/'application.xml').write_text('<application xmlns="http://ns.adobe.com/air/application/51.2"><id>local.starpoint.row.'+out.name+'</id><versionNumber>1.0.0</versionNumber><filename>row</filename><initialWindow><content>Launcher.swf</content><visible>false</visible></initialWindow></application>','utf-8');run=subprocess.run([str(sdk/'bin/adl64.exe'),'-nodebug',str(out/'application.xml')],cwd=out,capture_output=True,timeout=25);(out/'adl.log').write_bytes(run.stdout+run.stderr);result=json.loads((out/'result.json').read_text('utf-8')) if (out/'result.json').exists() else json.loads((out/'launcher.json').read_text('utf-8'));print(json.dumps({'exit_code':run.returncode,'result':result},ensure_ascii=False));assert run.returncode==0 and result['passed']
if __name__=='__main__':main()
